import { IOStateData } from '../data/IOStateData';
import { MessageEvent } from '../data/SignalR/SignalREventTypes';
import { LogCategory, Logger } from './Logger';
import { SignalRManager } from './SignalRManager';

/**
 * SignalRIOUpdater - Listens for I/O status messages and updates IOStateData
 * Handles messages like:
 * - "S198 Output 7 On" 
 * - "S134 Input 7 Closed"
 * - "S135 Input 7 Open"
 */
export class SignalRIOUpdater {
    private static _instance: SignalRIOUpdater;
    private _isListening: boolean = false;

    private constructor() {
        // Private constructor for singleton pattern
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): SignalRIOUpdater {
        if (!SignalRIOUpdater._instance) {
            SignalRIOUpdater._instance = new SignalRIOUpdater();
        }
        return SignalRIOUpdater._instance;
    }

    /**
     * Start listening for I/O status messages
     */
    public startListening(): void {
        if (this._isListening) {
            return;
        }

        SignalRManager.Instance.addEventListener('MessageEvent', this._handleMessageEvent);
        this._isListening = true;

        Logger.Instance.log(LogCategory.DataManager, 'SignalRIOUpdater started listening for I/O status messages');
    }

    /**
     * Stop listening for I/O status messages
     */
    public stopListening(): void {
        if (!this._isListening) {
            return;
        }

        SignalRManager.Instance.removeEventListener('MessageEvent', this._handleMessageEvent);
        this._isListening = false;

        Logger.Instance.log(LogCategory.DataManager, 'SignalRIOUpdater stopped listening for I/O status messages');
    }

    /**
     * Handle MessageEvent from SignalR and parse I/O status messages
     */
    private _handleMessageEvent = (event: MessageEvent): void => {
        try {
            const message = event.data.message;
            if (!message) {
                return;
            }

            // Parse I/O status messages
            const ioUpdate = this._parseIOStatusMessage(message);
            if (ioUpdate) {
                this._updateIOState(ioUpdate);
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling I/O message event:', error);
        }
    };

    /**
     * Parse I/O status messages into structured data
     * @param message The raw message string (e.g., "S198 Output 7 On")
     * @returns Parsed I/O update or null if not an I/O message
     */
    private _parseIOStatusMessage(message: string): IOStatusUpdate | null {
        // Match patterns:
        // S198 Output 7 On
        // S134 Input 7 Closed  
        // S135 Input 7 Open
        const outputPattern = /^S\d+\s+Output\s+(\d+)\s+(On|Off)$/i;
        const inputPattern = /^S\d+\s+Input\s+(\d+)\s+(Closed|Open)$/i;

        let match = message.match(outputPattern);
        if (match) {
            const number = parseInt(match[1], 10);
            const isActive = match[2].toLowerCase() === 'on';
            return {
                type: 'output',
                number,
                isActive,
                originalMessage: message
            };
        }

        match = message.match(inputPattern);
        if (match) {
            const number = parseInt(match[1], 10);
            const isActive = match[2].toLowerCase() === 'closed';
            return {
                type: 'input',
                number,
                isActive,
                originalMessage: message
            };
        }

        return null;
    }

    /**
     * Update IOStateData with the parsed I/O status
     */
    private _updateIOState(update: IOStatusUpdate): void {
        if (!IOStateData.Instance.isInitialized) {
            Logger.Instance.log(LogCategory.DataManager, 'IOStateData not initialized - skipping I/O update');
            return;
        }

        try {
            if (update.type === 'input') {
                IOStateData.Instance.updateInputState(update.number, update.isActive);
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `Updated input ${update.number} to ${update.isActive ? 'ACTIVE' : 'INACTIVE'} via SignalR`
                );
            } else if (update.type === 'output') {
                IOStateData.Instance.updateOutputState(update.number, update.isActive);
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `Updated output ${update.number} to ${update.isActive ? 'ACTIVE' : 'INACTIVE'} via SignalR`
                );
            }
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.DataManager,
                `Error updating ${update.type} ${update.number} state:`,
                error
            );
        }
    }

    /**
     * Get current listening status
     */
    public get isListening(): boolean {
        return this._isListening;
    }
}

/**
 * Parsed I/O status update
 */
interface IOStatusUpdate {
    type: 'input' | 'output';
    number: number;
    isActive: boolean;
    originalMessage: string;
}